+    /* if expected != -1, after we've read >= expected, we're "closed" and return -1
+     * from subsequent read() 's
+     */
@@ -44,1 +48,0 @@
-        assert expected > 0 : "Invalid content length: " + expected;
@@ -50,1 +53,1 @@
